// SYSCALL: User -> Kernel Mode Transition for I/O
// read() wrapper executes the SYSCALL instruction/trap
#define FD STDIN_FILENO
#define SIZE 1024
char buf[SIZE];

// CPU transitions from user mode to kernel mode (ring 0)
// RAX register holds the syscall number (e.g., 0 for read)
ssize_t count = read(FD, buf, SIZE);

// Kernel executes the handler, then returns to user mode
if (count < 0) {
    // Error handling
}


// ECF: Process Creation (fork/exec)
// System call resulting in exceptional control flow (new process)
pid_t pid = fork();

if (pid == 0) {
    // Child process: New execution thread
    char *args[] = {"/bin/echo", "Hello", NULL};
    // execv replaces the current process image
    execv(args[0], args);
    _exit(1);
} else if (pid > 0) {
    // Parent process
    int status;
    // Parent blocks, waiting for child ECF completion
    waitpid(pid, &status, 0);
}
